ACPI_STATUS AcpiPsCompleteThisOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Parent;
    ACPI_PARSE_OBJECT *Next;
    ACPI_OPERAND_OBJECT *Value;

    /* Check if the operation is valid */
    if (!Op) {
        return (AE_BAD_PARAMETER);
    }

    /* If there is an ascending callback, call it */
    if (WalkState->DescendingCallback && WalkState->AscendingCallback) {
        Status = WalkState->AscendingCallback(WalkState, Op, Status);
        if (ACPI_FAILURE(Status)) {
            return (Status);
        }
    }

    Parent = Op->Common.Parent;

    /* If this is a prefix operator, we need to create a new Op */
    if (Op->Named.Object && Op->Named.OpInfo->Type == ACPI_PARSE_OPCODE_PREFIX) {
        Next = AcpiPsCreateOp(WalkState, Op->Named.OpInfo);
        if (!Next) {
            return (AE_NO_MEMORY);
        }

        Next->Common.Parent = Op;
        Op->Common.Value.Arg = Next;
    }

    /* If this Op has a value, push it on the operand stack */
    if (Op->Common.Value.Obj) {
        Value = Op->Common.Value.Obj;

        if (ACPI_SUCCESS(Status)) {
            Status = AcpiExStoreValue(Value, WalkState->ResultObj);
        }

        if (ACPI_SUCCESS(Status)) {
            WalkState->ResultObj = Value;
        }
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteThisOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ParentOp;

    /* Validate input */
    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* If no error occurred or the error is not fatal, process the ascending callback */
    if (ACPI_SUCCESS(Status) || (Status == AE_CTRL_CONTINUE)) {
        if (WalkState->DescendingCallback && WalkState->AscendingCallback) {
            Status = WalkState->AscendingCallback(WalkState, Op, Status);
        }
    }

    /* Check if we need to continue processing */
    if (Status == AE_CTRL_TRANSFER || Status == AE_CTRL_EXIT || Status == AE_CTRL_CONTINUE) {
        return (Status);
    }

    /* If an error occurred, return it */
    if (ACPI_FAILURE(Status)) {
        return (Status);
    }

    /* Get the parent of the current Op */
    ParentOp = Op->Common.Parent;

    /* If the Op has no parent, we're at the root of the parse tree */
    if (!ParentOp) {
        WalkState->ParseTreeRoot = NULL;
    }

    return (AE_OK);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *ScopeOp;
    ACPI_PARSE_OBJECT *PrevOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Get the scope op from the walk state */
    ScopeOp = WalkState->Scope.Op;

    if (ScopeOp) {
        if (ScopeOp == Op) {
            /* If this is the closing op, pop the scope */
            WalkState->Scope.Op = WalkState->Scope.NestOp;
            WalkState->Scope.Next = WalkState->Scope.Next->Next;
        }
    }

    if (WalkState->ParseTreeRoot == Op) {
        WalkState->ParseTreeRoot = NULL;
    }

    if (Status == AE_CTRL_TRANSFERRED) {
        PrevOp = Op->Common.Parent;
        if (PrevOp && PrevOp->Common.Value.Arg) {
            Op->Common.Value.Arg = PrevOp->Common.Value.Arg;
            PrevOp->Common.Value.Arg = NULL;
        }
    }

    if (Status == AE_CTRL_CONTINUE) {
        WalkState->ControlState = WalkState->ControlState->Next;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteThisOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->Ctrl.State == PSI_CONT)
    {
        if (WalkState->Ctrl.AscendingCallback)
        {
            Status = WalkState->Ctrl.AscendingCallback(WalkState, Op, Status, WalkState->Ctrl.AscendingContext);
            if (Status != AE_OK && Status != AE_CTRL_CONTINUE)
            {
                return (Status);
            }
        }
    }

    PrevOp = Op->Common.Next;

    if (WalkState->ParserState.ScopeDepth > 0)
    {
        WalkState->ParserState.ScopeDepth--;
    }

    WalkState->ParserState.CurrentOp = PrevOp;

    return (Status);
}

ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->Control.MethodCount == 0) {
        return (AE_AML_STACK UNDERFLOW);
    }

    if (Status != AE_CTRL_TRANSFERRED) {
        if (Status != AE_CTRL_PENDING) {
            if (Status != AE_OK) {
                WalkState->Result = NULL;
            }

            if (Op->Asl.Value.ArgList) {
                AcpiUtRemoveReference(Op->Asl.Value.ArgList);
            }
        }
    }

    if (WalkState->Control.AscendingCallback) {
        Status = WalkState->Control.AscendingCallback(WalkState, Op, WalkState->Result, WalkState->Control.Descriptor);
        if (Status == AE_CTRL_PENDING) {
            WalkState->Control.ResultNeeded = TRUE;
            return (AE_OK);
        }
    }

    PrevOp = WalkState->ParserState.Next;
    if (PrevOp) {
        if (PrevOp->Common.AmlOpcode == AML_RETURN_OP) {
            WalkState->Control.ResultNeeded = TRUE;
        }
    }

    WalkState->Control.MethodCount--;
    return (Status);
}
